  create policy "Users can delete their own memories"
  on "public"."memories"
  as permissive
  for delete
  to authenticated
using ((auth.uid() = user_id));



  create policy "Users can insert their own memories"
  on "public"."memories"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = user_id));



  create policy "Users can update their own memories"
  on "public"."memories"
  as permissive
  for update
  to authenticated
using ((auth.uid() = user_id));



  create policy "Users can view their own memories"
  on "public"."memories"
  as permissive
  for select
  to authenticated
using ((auth.uid() = user_id));



  create policy "Users can delete their own memory sections"
  on "public"."memory_sections"
  as permissive
  for delete
  to authenticated
using ((memory_id IN ( SELECT memories.id
   FROM memories
  WHERE (memories.user_id = auth.uid()))));



  create policy "Users can insert memory sections"
  on "public"."memory_sections"
  as permissive
  for insert
  to authenticated
with check ((memory_id IN ( SELECT memories.id
   FROM memories
  WHERE (memories.user_id = auth.uid()))));



  create policy "Users can view their own memory sections"
  on "public"."memory_sections"
  as permissive
